-- DAT-008 (E5 secrets): the PINNED version of an execution-secret handle's `ref_id`,
-- so a handle bound to an agent's own secret_ref resolves the version that agent
-- pinned rather than silently moving to `latest`. A version selector, never a value.
-- Generated by `drizzle-kit generate`; the C14 idempotency guard (`IF NOT EXISTS` on
-- the ADD COLUMN) was hand-appended after generation so a partial-apply replay is a
-- no-op (repo convention, enforced by migration-idempotency.test.ts +
-- migration-readiness). Schema DDL is NOT hand-authored — only the guard is.
--
-- Nullable additive widen of an already-distributed table, so it inherits the existing
-- whole-table `aoa_app` grant and FORCE-RLS policy with no keystone reconciliation.
ALTER TABLE "job_secret_handles" ADD COLUMN IF NOT EXISTS "ref_version" text;
